import 'dart:async';import 'dart:convert';import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:http/http.dart' as http;import 'package:http/testing.dart';
import 'package:flutter_core/preference_sync.dart';
class MemoryCache implements PreferenceCache {
 final values=<String,String>{};bool denied=false;
 @override Future<String?> read(String key)async=>values[key];
 @override Future<void> write(String key,String value)async{if(denied)throw StateError('denied');values[key]=value;}
 @override Future<void> remove(String key)async{values.remove(key);}
}
class RemovalCache extends MemoryCache {
 final started=Completer<void>(), release=Completer<void>();bool fail=false;
 @override Future<void> remove(String key)async{started.complete();await release.future;if(fail)throw StateError('denied');await super.remove(key);}
}
class BlockingWriteCache extends MemoryCache {
 final started=Completer<void>(),release=Completer<void>();bool blocked=false;
 @override Future<void> write(String key,String value)async{if(blocked){if(!started.isCompleted)started.complete();await release.future;}await super.write(key,value);}
}
final scope=PreferenceScope('tenant1','user1','psw','live');
PreferenceBinding binding()=>PreferenceBinding(scope:scope,kind:'shortcuts',resource:'navigation',screenIds:['1','2']);
Map<String,dynamic> doc(String id)=>{'version':1,'screenIds':[id]};
Object? clone(Object? value)=>jsonDecode(jsonEncode(value));
class Server {
 late Map<String,dynamic> snapshot={'version':1,'scope':scope.toJson(),'kind':'shortcuts','resource':'navigation','revision':0,'document':null};
 final receipts=<String,Object?>{};bool offline=false,lost=false;Completer<void>? block;
 Future<Object?> call(Map<String,dynamic> r)async{if(offline)throw StateError('offline');if(r['action']=='read')return clone(snapshot);if(block!=null)await block!.future;final id=r['requestId'] as String;if(receipts.containsKey(id))return clone(receipts[id]);if(r['revision']!=snapshot['revision'])throw PreferenceFailure('revision_conflict',409,clone(snapshot));snapshot={...snapshot,'revision':(snapshot['revision'] as int)+1,'document':r['action']=='write'?r['document']:null};receipts[id]=clone(snapshot);if(lost){lost=false;throw StateError('lost');}return clone(snapshot);}
}
void main(){
 test('disposal during durable storage prevents dispatch and retains explicit retry',()async{
  final s=Server(),cache=BlockingWriteCache();var calls=0;
  final a=PreferenceSyncClient(binding:binding(),transport:(request)async{if(request['action']!='read')calls++;return s.call(request);},cache:cache);
  await a.load();await a.edit(doc('1'));cache.blocked=true;final saving=a.save();await cache.started.future;
  a.dispose();cache.release.complete();await saving;await a.settled;
  expect(calls,0);expect(s.snapshot['revision'],0);expect(a.current['status'],'disposed');
  final b=PreferenceSyncClient(binding:binding(),transport:s.call,cache:cache);await b.load();expect(s.snapshot['revision'],0);expect(b.current['pending'],isNotNull);
  await b.retryPending();expect(s.snapshot['revision'],1);b.dispose();await b.settled;
 });
 test('shared TypeScript protocol oracle matches native normalization and rejection',(){final fixture=jsonDecode(File('test/preference_sync/protocol-fixtures.json').readAsStringSync()) as Map<String,dynamic>;final policy=fixture['policy'] as Map<String,dynamic>,bound=PreferenceBinding(scope:scope,kind:'shortcuts',resource:'navigation',panelIds:(policy['panelIds'] as List).cast<String>(),screenIds:(policy['screenIds'] as List).cast<String>());for(final raw in fixture['cases'] as List){final c=raw as Map<String,dynamic>;if(c.containsKey('error')){expect(()=>preferenceRequest(c['input'],bound),throwsA(isA<PreferenceFailure>().having((e)=>e.code,'code',c['error'])),reason:c['name'] as String);}else{expect(preferenceRequest(c['input'],bound),c['output'],reason:c['name'] as String);}}});
 test('native HTTP adapter uses registered bearer POST and bounds responses',()async{final server=Server(),requests=<http.Request>[],adapter=PreferenceHttpTransport(origin:Uri.parse('https://fixture.test/'),token:'a'*43,client:MockClient((r)async{requests.add(r);return http.Response(jsonEncode(await server.call(jsonDecode(r.body) as Map<String,dynamic>)),200);})),a=PreferenceSyncClient(binding:binding(),transport:adapter.call,cache:MemoryCache());await a.load();await a.edit(doc('1'));await a.save();expect(a.current['status'],'clean');expect(requests.length,2);for(final r in requests){expect(r.url.toString(),'https://fixture.test/v1/user/preferences');expect(r.method,'POST');expect(r.headers['authorization'],'Bearer ${'a'*43}');expect(r.followRedirects,false);}adapter.close();final conflict=PreferenceHttpTransport(origin:Uri.parse('https://fixture.test'),token:'a'*43,client:MockClient((_)async=>http.Response(jsonEncode({'error':'revision_conflict','current':server.snapshot}),409)));await expectLater(conflict.call({}),throwsA(isA<PreferenceFailure>().having((e)=>e.code,'code','revision_conflict')));conflict.close();final huge=PreferenceHttpTransport(origin:Uri.parse('https://fixture.test'),token:'a'*43,client:MockClient((_)async=>http.Response('x'*262145,200)));await expectLater(huge.call({}),throwsA(isA<PreferenceFailure>().having((e)=>e.code,'code','invalid_response')));huge.close();expect(()=>PreferenceHttpTransport(origin:Uri.parse('https://fixture.test/arbitrary'),token:'a'*43),throwsA(isA<PreferenceFailure>()));});
 test('two device CAS conflicts, explicit resolution, reload and tombstones',()async{final s=Server(),cache=MemoryCache(),a=PreferenceSyncClient(binding:binding(),transport:s.call,cache:MemoryCache()),b=PreferenceSyncClient(binding:binding(),transport:s.call,cache:cache);await a.load();await b.load();await a.edit(doc('1'));await a.save();await b.edit(doc('2'));await b.save();expect(b.current['status'],'conflict');await b.keepLocal();await b.save();expect(s.snapshot['revision'],2);final reload=PreferenceSyncClient(binding:binding(),transport:s.call,cache:cache);await reload.load();expect(reload.current['draft'],doc('2'));await a.edit(doc('1'));await a.save();await a.acceptRemote();expect(a.current['draft'],doc('2'));await a.edit(null);await a.save('reset');await a.save('delete');expect(s.snapshot['revision'],4);expect(s.snapshot['document'],null);});
 test('lost acknowledgement persists UUID across restart and explicit replay',()async{final s=Server(),cache=MemoryCache(),a=PreferenceSyncClient(binding:binding(),transport:s.call,cache:cache);await a.load();await a.edit(doc('1'));s.lost=true;await a.save();final pending=(a.current['pending'] as Map)['requestId'];expect(a.current['status'],'offline');a.dispose();await a.settled;final b=PreferenceSyncClient(binding:binding(),transport:s.call,cache:cache);await b.load();expect(b.current['status'],'conflict');expect((b.current['pending'] as Map)['requestId'],pending);await b.retryPending();expect(b.current['status'],'clean');expect(s.snapshot['revision'],1);});
 test('restart after lost acknowledgement preserves newer cached draft',()async{final s=Server(),cache=MemoryCache(),a=PreferenceSyncClient(binding:binding(),transport:s.call,cache:cache);await a.load();await a.edit(doc('1'));s.lost=true;await a.save();await a.edit(doc('2'));a.dispose();await a.settled;final b=PreferenceSyncClient(binding:binding(),transport:s.call,cache:cache);await b.load();await b.retryPending();expect(b.current['status'],'dirty');expect(b.current['draft'],doc('2'));await b.save();expect(s.snapshot['document'],doc('2'));expect(s.snapshot['revision'],2);});
 test('offline first load permits durable CAS queue, no automatic retry',()async{final s=Server()..offline=true,a=PreferenceSyncClient(binding:binding(),transport:s.call,cache:MemoryCache());await a.load();await a.edit(doc('1'));await a.save();expect(a.current['status'],'offline');s.offline=false;expect(s.snapshot['revision'],0);await a.retryPending();expect(s.snapshot['revision'],1);});
 test('refresh and in-flight acknowledgement preserve newer edits',()async{final s=Server(),a=PreferenceSyncClient(binding:binding(),transport:s.call,cache:MemoryCache());await a.load();await a.edit(doc('1'));await a.load();expect(a.current['draft'],doc('1'));s.block=Completer<void>();final saving=a.save();await Future<void>.delayed(Duration.zero);await a.edit(doc('2'));s.block!.complete();await saving;expect(a.current['status'],'dirty');expect(a.current['draft'],doc('2'));});
 test('cache failure prevents network mutation and scope migration is explicit',()async{final s=Server(),cache=MemoryCache(),a=PreferenceSyncClient(binding:binding(),transport:s.call,cache:cache);await a.load();await expectLater(a.adoptLocal(doc('1'),PreferenceScope('tenant1','other','psw','live')),throwsA(isA<PreferenceFailure>()));await a.edit(doc('1'));cache.denied=true;await a.save();expect(a.current['error'],'cache_unavailable');expect(s.snapshot['revision'],0);await expectLater(a.edit(doc('99')),throwsA(isA<PreferenceFailure>()));});
 test('disposed actor ignores delayed completion; identity and schema checks are strict',()async{final ready=Completer<Object?>(),a=PreferenceSyncClient(binding:binding(),transport:(_)=>ready.future,cache:MemoryCache()),loading=a.load();await Future<void>.delayed(Duration.zero);a.dispose();ready.complete(Server().snapshot);await loading;expect(a.current['status'],'disposed');expect((a.current['base'] as Map)['revision'],0);expect(()=>preferenceSnapshot({...Server().snapshot,'scope':PreferenceScope('tenant2','user1','psw','live').toJson()},binding()),throwsA(isA<PreferenceFailure>()));expect(()=>preferenceRequest({'version':1,'action':'read','dataset':'live','kind':'shortcuts','resource':'navigation','expectedScope':scope.toJson(),'userId':'other'},binding()),throwsA(isA<PreferenceFailure>()));});
 test('discard locks edits and writes until storage completes',()async{final s=Server(),cache=RemovalCache(),a=PreferenceSyncClient(binding:binding(),transport:s.call,cache:cache);await a.load();await a.edit(doc('1'));final discard=a.discardLocal();await cache.started.future;expect(a.current['status'],'discarding');for(final action in <Future<void> Function()>[()=>a.edit(doc('2')),()=>a.save(),()=>a.load(),()=>a.discardLocal()]){await expectLater(action(),throwsA(isA<PreferenceFailure>()));}cache.release.complete();await discard;expect(a.current['status'],'idle');expect(s.snapshot['revision'],0);a.dispose();});
 test('failed discard retains draft and reports storage failure',()async{final cache=RemovalCache()..fail=true,a=PreferenceSyncClient(binding:binding(),transport:Server().call,cache:cache);await a.load();await a.edit(doc('1'));final discard=a.discardLocal();await cache.started.future;cache.release.complete();await expectLater(discard,throwsA(isA<PreferenceFailure>().having((e)=>e.code,'code','cache_unavailable')));expect(a.current['error'],'cache_unavailable');expect(a.current['draft'],doc('1'));await a.edit(doc('2'));expect(a.current['draft'],doc('2'));a.dispose();});
 test('late discard completion preserves disposed status',()async{final cache=RemovalCache(),a=PreferenceSyncClient(binding:binding(),transport:Server().call,cache:cache);await a.load();await a.edit(doc('1'));final discard=a.discardLocal();await cache.started.future;a.dispose();cache.release.complete();await discard;expect(a.current['status'],'disposed');expect(a.current['draft'],doc('1'));});

}
